18	package org.apache.hadoop.ozone.om.response.key;
19	
20	import static org.apache.hadoop.ozone.om.codec.OMDBDefinition.BUCKET_TABLE;
21	import static org.apache.hadoop.ozone.om.codec.OMDBDefinition.DELETED_TABLE;
22	import static org.apache.hadoop.ozone.om.codec.OMDBDefinition.KEY_TABLE;
23	import static org.apache.hadoop.ozone.om.codec.OMDBDefinition.OPEN_KEY_TABLE;
24	
25	import com.google.common.annotations.VisibleForTesting;
26	import jakarta.annotation.Nonnull;
27	import java.io.IOException;
28	import java.util.Map;
29	import org.apache.hadoop.hdds.utils.db.BatchOperation;
30	import org.apache.hadoop.ozone.om.OMMetadataManager;
31	import org.apache.hadoop.ozone.om.helpers.BucketLayout;
32	import org.apache.hadoop.ozone.om.helpers.OmBucketInfo;
33	import org.apache.hadoop.ozone.om.helpers.OmKeyInfo;
34	import org.apache.hadoop.ozone.om.helpers.RepeatedOmKeyInfo;
35	import org.apache.hadoop.ozone.om.response.CleanupTableInfo;
36	import org.apache.hadoop.ozone.protocol.proto.OzoneManagerProtocolProtos.OMResponse;
37	
38	/**
39	 * Response for CommitKey request.
40	 */
41	@CleanupTableInfo(cleanupTables = {OPEN_KEY_TABLE, KEY_TABLE, DELETED_TABLE,
42	    BUCKET_TABLE})
43	public class OMKeyCommitResponse extends OmKeyResponse {
44	
45	  private OmKeyInfo omKeyInfo;
46	  private String ozoneKeyName;
47	  private String openKeyName;
48	  private OmBucketInfo omBucketInfo;
49	  private Map<String, RepeatedOmKeyInfo> keyToDeleteMap;
50	  private boolean isHSync;
51	  private OmKeyInfo newOpenKeyInfo;
52	  private OmKeyInfo openKeyToUpdate;
53	  private String openKeyNameToUpdate;
54	
55	  @SuppressWarnings("checkstyle:ParameterNumber")
56	  public OMKeyCommitResponse(
57	      @Nonnull OMResponse omResponse,
58	      @Nonnull OmKeyInfo omKeyInfo, String ozoneKeyName, String openKeyName,
59	      @Nonnull OmBucketInfo omBucketInfo,
60	      Map<String, RepeatedOmKeyInfo> keyToDeleteMap,
61	      boolean isHSync,
62	      OmKeyInfo newOpenKeyInfo, String openKeyNameToUpdate, OmKeyInfo openKeyToUpdate) {
63	    super(omResponse, omBucketInfo.getBucketLayout());
64	    this.omKeyInfo = omKeyInfo;
65	    this.ozoneKeyName = ozoneKeyName;
66	    this.openKeyName = openKeyName;
67	    this.omBucketInfo = omBucketInfo;
68	    this.keyToDeleteMap = keyToDeleteMap;
69	    this.isHSync = isHSync;
70	    this.newOpenKeyInfo = newOpenKeyInfo;
71	    this.openKeyNameToUpdate = openKeyNameToUpdate;
72	    this.openKeyToUpdate = openKeyToUpdate;
73	  }
74	
75	  /**
76	   * For when the request is not successful.
77	   * For a successful request, the other constructor should be used.
78	   */
79	  public OMKeyCommitResponse(@Nonnull OMResponse omResponse, @Nonnull
80	      BucketLayout bucketLayout) {
81	    super(omResponse, bucketLayout);
82	    checkStatusNotOK();
83	  }
84	
85	  @Override
86	  public void addToDBBatch(OMMetadataManager omMetadataManager,
87	      BatchOperation batchOperation) throws IOException {
88	
89	    // Delete from OpenKey table
90	    if (!isHSync()) {
91	      omMetadataManager.getOpenKeyTable(getBucketLayout())
92	          .deleteWithBatch(batchOperation, openKeyName);
93	    } else if (newOpenKeyInfo != null) {
94	      omMetadataManager.getOpenKeyTable(getBucketLayout()).putWithBatch(
95	          batchOperation, openKeyName, newOpenKeyInfo);
96	    }
97	
98	    omMetadataManager.getKeyTable(getBucketLayout())
99	        .putWithBatch(batchOperation, ozoneKeyName, omKeyInfo);
100	
101	    updateDeletedTable(omMetadataManager, batchOperation);
102	    handleOpenKeyToUpdate(omMetadataManager, batchOperation);
103	
104	    // update bucket usedBytes.
105	    omMetadataManager.getBucketTable().putWithBatch(batchOperation,
106	        omMetadataManager.getBucketKey(omBucketInfo.getVolumeName(),
107	            omBucketInfo.getBucketName()), omBucketInfo);
108	  }
109	
110	  protected String getOpenKeyName() {
111	    return openKeyName;
112	  }
113	
114	  protected OmKeyInfo getOmKeyInfo() {
115	    return omKeyInfo;
116	  }
117	
118	  protected OmBucketInfo getOmBucketInfo() {
119	    return omBucketInfo;
120	  }
121	
122	  protected String getOzoneKeyName() {
123	    return ozoneKeyName;
124	  }
125	
126	  @VisibleForTesting
127	  public Map<String, RepeatedOmKeyInfo> getKeysToDelete() {
128	    return keyToDeleteMap;
129	  }
130	
131	  protected void updateDeletedTable(OMMetadataManager omMetadataManager,
132	      BatchOperation batchOperation) throws IOException {
133	    if (this.keyToDeleteMap != null) {
134	      for (Map.Entry<String, RepeatedOmKeyInfo> entry : 
135	          keyToDeleteMap.entrySet()) {
136	        omMetadataManager.getDeletedTable().putWithBatch(batchOperation,
137	            entry.getKey(), entry.getValue());
138	      }
139	    }
140	  }
141	
142	  protected void handleOpenKeyToUpdate(OMMetadataManager omMetadataManager,
143	      BatchOperation batchOperation) throws IOException {
144	    if (this.openKeyToUpdate != null) {
145	      omMetadataManager.getOpenKeyTable(getBucketLayout()).putWithBatch(
146	          batchOperation, openKeyNameToUpdate, openKeyToUpdate);
147	    }
148	  }
149	
150	  protected boolean isHSync() {
151	    return isHSync;
152	  }
153	
154	  public OmKeyInfo getNewOpenKeyInfo() {
155	    return newOpenKeyInfo;
156	  }
157	}
