42	    BUCKET_TABLE})
43	public class OMKeyCommitResponseWithFSO extends OMKeyCommitResponse {
44	
45	  private long volumeId;
46	
47	  @SuppressWarnings("checkstyle:ParameterNumber")
48	  public OMKeyCommitResponseWithFSO(
49	      @Nonnull OMResponse omResponse,
50	      @Nonnull OmKeyInfo omKeyInfo,
51	      String ozoneKeyName, String openKeyName,
52	      @Nonnull OmBucketInfo omBucketInfo,
53	      Map<String, RepeatedOmKeyInfo> deleteKeyMap, long volumeId,
54	      boolean isHSync,
55	      OmKeyInfo newOpenKeyInfo, String openKeyNameToUpdate, OmKeyInfo openKeyToUpdate) {
56	    super(omResponse, omKeyInfo, ozoneKeyName, openKeyName,
57	        omBucketInfo, deleteKeyMap, isHSync, newOpenKeyInfo, openKeyNameToUpdate, openKeyToUpdate);
58	    this.volumeId = volumeId;
59	  }
60	
61	  /**
62	   * For when the request is not successful.
63	   * For a successful request, the other constructor should be used.
64	   */
65	  public OMKeyCommitResponseWithFSO(@Nonnull OMResponse omResponse,
66	                                    @Nonnull BucketLayout bucketLayout) {
67	    super(omResponse, bucketLayout);
68	    checkStatusNotOK();
69	  }
70	
71	  @Override
72	  public void addToDBBatch(OMMetadataManager omMetadataManager,
73	                           BatchOperation batchOperation) throws IOException {
74	
75	    // Delete from OpenKey table if commit
76	    if (!this.isHSync()) {
77	      omMetadataManager.getOpenKeyTable(getBucketLayout())
78	          .deleteWithBatch(batchOperation, getOpenKeyName());
79	    } else if (getNewOpenKeyInfo() != null) {
80	      omMetadataManager.getOpenKeyTable(getBucketLayout()).putWithBatch(
81	          batchOperation, getOpenKeyName(), getNewOpenKeyInfo());
82	    }
83	
84	    OMFileRequest.addToFileTable(omMetadataManager, batchOperation,
85	        getOmKeyInfo(), volumeId, getOmBucketInfo().getObjectID());
86	
87	    updateDeletedTable(omMetadataManager, batchOperation);
88	    handleOpenKeyToUpdate(omMetadataManager, batchOperation);
89	
90	    // update bucket usedBytes.
91	    omMetadataManager.getBucketTable().putWithBatch(batchOperation,
92	        omMetadataManager.getBucketKey(getOmBucketInfo().getVolumeName(),
93	            getOmBucketInfo().getBucketName()), getOmBucketInfo());
94	  }
95	
96	  @Override
97	  public BucketLayout getBucketLayout() {
98	    return BucketLayout.FILE_SYSTEM_OPTIMIZED;
99	  }
