18	package org.apache.hadoop.ozone.om.response.s3.multipart;
19	
20	import static org.apache.hadoop.ozone.om.codec.OMDBDefinition.BUCKET_TABLE;
21	import static org.apache.hadoop.ozone.om.codec.OMDBDefinition.DELETED_TABLE;
22	import static org.apache.hadoop.ozone.om.codec.OMDBDefinition.MULTIPART_INFO_TABLE;
23	import static org.apache.hadoop.ozone.om.codec.OMDBDefinition.OPEN_KEY_TABLE;
24	import static org.apache.hadoop.ozone.protocol.proto.OzoneManagerProtocolProtos.Status.NO_SUCH_MULTIPART_UPLOAD_ERROR;
25	import static org.apache.hadoop.ozone.protocol.proto.OzoneManagerProtocolProtos.Status.OK;
26	
27	import jakarta.annotation.Nonnull;
28	import jakarta.annotation.Nullable;
29	import java.io.IOException;
30	import org.apache.hadoop.hdds.utils.db.BatchOperation;
31	import org.apache.hadoop.ozone.OmUtils;
32	import org.apache.hadoop.ozone.om.OMMetadataManager;
33	import org.apache.hadoop.ozone.om.helpers.BucketLayout;
34	import org.apache.hadoop.ozone.om.helpers.OmBucketInfo;
35	import org.apache.hadoop.ozone.om.helpers.OmKeyInfo;
36	import org.apache.hadoop.ozone.om.helpers.OmMultipartKeyInfo;
37	import org.apache.hadoop.ozone.om.helpers.RepeatedOmKeyInfo;
38	import org.apache.hadoop.ozone.om.response.CleanupTableInfo;
39	import org.apache.hadoop.ozone.om.response.key.OmKeyResponse;
40	import org.apache.hadoop.ozone.protocol.proto.OzoneManagerProtocolProtos;
41	import org.apache.hadoop.ozone.protocol.proto.OzoneManagerProtocolProtos.OMResponse;
42	
43	/**
44	 * Response for S3MultipartUploadCommitPart request.
45	 */
46	@CleanupTableInfo(cleanupTables = {OPEN_KEY_TABLE, DELETED_TABLE,
47	    MULTIPART_INFO_TABLE, BUCKET_TABLE})
48	public class S3MultipartUploadCommitPartResponse extends OmKeyResponse {
49	
50	  private String multipartKey;
51	  private String openKey;
52	  private OmMultipartKeyInfo omMultipartKeyInfo;
53	  private OzoneManagerProtocolProtos.PartKeyInfo oldPartKeyInfo;
54	  private OmKeyInfo openPartKeyInfoToBeDeleted;
55	  private OmBucketInfo omBucketInfo;
56	
57	  /**
58	   * Regular response.
59	   * 1. Update MultipartKey in MultipartInfoTable with new PartKeyInfo
60	   * 2. Delete openKey from OpenKeyTable
61	   * 3. If old PartKeyInfo exists, put it in DeletedKeyTable
62	   * @param omResponse
63	   * @param multipartKey
64	   * @param openKey
65	   * @param omMultipartKeyInfo
66	   * @param oldPartKeyInfo
67	   * @param openPartKeyInfoToBeDeleted
68	   * @param omBucketInfo
69	   */
70	  @SuppressWarnings("checkstyle:ParameterNumber")
71	  public S3MultipartUploadCommitPartResponse(@Nonnull OMResponse omResponse,
72	      String multipartKey, String openKey,
73	      @Nullable OmMultipartKeyInfo omMultipartKeyInfo,
74	      @Nullable OzoneManagerProtocolProtos.PartKeyInfo oldPartKeyInfo,
75	      @Nullable OmKeyInfo openPartKeyInfoToBeDeleted,
76	      @Nonnull OmBucketInfo omBucketInfo,
77	      @Nonnull BucketLayout bucketLayout) {
78	    super(omResponse, bucketLayout);
79	    this.multipartKey = multipartKey;
80	    this.openKey = openKey;
81	    this.omMultipartKeyInfo = omMultipartKeyInfo;
82	    this.oldPartKeyInfo = oldPartKeyInfo;
83	    this.openPartKeyInfoToBeDeleted = openPartKeyInfoToBeDeleted;
84	    this.omBucketInfo = omBucketInfo;
85	  }
86	
87	  @Override
88	  public void checkAndUpdateDB(OMMetadataManager omMetadataManager,
89	      BatchOperation batchOperation) throws IOException {
90	
91	    if (getOMResponse().getStatus() == NO_SUCH_MULTIPART_UPLOAD_ERROR) {
92	      // Means by the time we try to commit part, some one has aborted this
93	      // multipart upload. So, delete this part information.
94	
95	      RepeatedOmKeyInfo repeatedOmKeyInfo =
96	          OmUtils.prepareKeyForDelete(openPartKeyInfoToBeDeleted,
97	              openPartKeyInfoToBeDeleted.getUpdateID()
98	          );
99	      // multi-part key format is volumeName/bucketName/keyName/uploadId
100	      String deleteKey = omMetadataManager.getOzoneDeletePathKey(
101	          openPartKeyInfoToBeDeleted.getObjectID(), multipartKey);
102	
103	      omMetadataManager.getDeletedTable().putWithBatch(batchOperation,
104	          deleteKey, repeatedOmKeyInfo);
105	    }
106	
107	    if (getOMResponse().getStatus() == OK) {
108	      addToDBBatch(omMetadataManager, batchOperation);
109	    }
110	  }
111	
112	  @Override
113	  public void addToDBBatch(OMMetadataManager omMetadataManager,
114	      BatchOperation batchOperation) throws IOException {
115	
116	    // If we have old part info:
117	    // Need to do 3 steps:
118	    //   0. Strip GDPR related metadata from multipart info
119	    //   1. add old part to delete table
120	    //   2. Commit multipart info which has information about this new part.
121	    //   3. delete this new part entry from open key table.
122	
123	    // This means for this multipart upload part upload, we have an old
124	    // part information, so delete it.
125	    if (oldPartKeyInfo != null) {
126	      OmKeyInfo partKeyToBeDeleted =
127	          OmKeyInfo.getFromProtobuf(oldPartKeyInfo.getPartKeyInfo());
128	
129	      RepeatedOmKeyInfo repeatedOmKeyInfo = OmUtils.prepareKeyForDelete(
130	          partKeyToBeDeleted,
131	          omMultipartKeyInfo.getUpdateID());
132	      // multi-part key format is volumeName/bucketName/keyName/uploadId
133	      String deleteKey = omMetadataManager.getOzoneDeletePathKey(
134	          partKeyToBeDeleted.getObjectID(), multipartKey);
135	
136	      omMetadataManager.getDeletedTable().putWithBatch(batchOperation,
137	          deleteKey, repeatedOmKeyInfo);
138	    }
139	
140	    omMetadataManager.getMultipartInfoTable().putWithBatch(batchOperation,
141	        multipartKey, omMultipartKeyInfo);
142	
143	    //  This information has been added to multipartKeyInfo. So, we can
144	    //  safely delete part key info from open key table.
145	    omMetadataManager.getOpenKeyTable(getBucketLayout())
146	        .deleteWithBatch(batchOperation, openKey);
147	
148	    // update bucket usedBytes.
149	    omMetadataManager.getBucketTable().putWithBatch(batchOperation,
150	        omMetadataManager.getBucketKey(omBucketInfo.getVolumeName(),
151	            omBucketInfo.getBucketName()), omBucketInfo);
152	  }
153	}
